            await _module.InvokeVoidAsync("initialize", _element, _dotNetRef, TimeoutSeconds);
        }
    }

    [JSInvokable]
    public async Task NotifyIdle()
    {
        await OnIdle.InvokeAsync();
    }

    [JSInvokable]
    public async Task NotifyActive()
    {
        await OnActive.InvokeAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
