let timer = null;
let dotNetHelper = null;
let isIdle = false;
let timeoutMs = 0;
let trackedElement = null;

const events = ["mousemove", "keydown", "click", "scroll"];

function onActivity() {
    if (isIdle) {
        isIdle = false;
        dotNetHelper.invokeMethodAsync("NotifyActive");
    }
    resetTimer();
}

function resetTimer() {
    clearTimeout(timer);
    timer = setTimeout(() => {
        isIdle = true;
        dotNetHelper.invokeMethodAsync("NotifyIdle");
    }, timeoutMs);
}

export function initialize(element, helper, timeoutSeconds) {
    trackedElement = element;
    dotNetHelper = helper;
    timeoutMs = timeoutSeconds * 1000;
    isIdle = false;

    events.forEach(e => trackedElement.addEventListener(e, onActivity, { passive: true }));
    resetTimer();
}

export function dispose() {
    clearTimeout(timer);
    timer = null;

    if (trackedElement) {
        events.forEach(e => trackedElement.removeEventListener(e, onActivity));
        trackedElement = null;
    }

    dotNetHelper = null;
    isIdle = false;
}

